<?php
namespace App\Http\Controllers\Portal;
use App\Http\Controllers\Controller;
use App\Models\{OperationsHandover,CrmPipelineProject,User,PerformanceEvent};
use App\Services\{OperationsHandoverWorkflow as Workflow,ClientRelationsPipeline as Pipeline,PerformanceWorkflow};
use App\Services\Creative\{CreativeAccess,CreativeUploadScreening};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Storage};
class OperationsHandoverController extends Controller {
 private function access(Request $r):void{abort_unless(CreativeAccess::staff($r->user()),403);}
 public function index(Request $r){$this->access($r);return view('portal.operations.handovers');}
 public function data(Request $r,Workflow $flow){$this->access($r);$f=$r->validate(['q'=>'nullable|string|max:150','stage'=>'nullable|in:submitted,acknowledged,handover_meeting,planning,sourcing,setup,awaiting_acceptance,accepted,completed,cancelled','page'=>'nullable|integer|min:1','handover'=>'nullable|integer|min:1']);
  $q=OperationsHandover::with('requester','lead','project')->when($r->filled('q'),fn($q)=>$q->where(fn($q)=>$q->where('title','like','%'.$f['q'].'%')->orWhereHas('project',fn($p)=>$p->where('client_name','like','%'.$f['q'].'%'))))->when($r->filled('stage'),fn($q)=>$q->where('stage',$f['stage']))->when($r->filled('handover'),fn($q)=>$q->whereKey($f['handover']));
  $rows=$q->orderByDesc('id')->paginate(10);$projects=Pipeline::member($r->user())?CrmPipelineProject::where('source_period_confirmed',true)->where(fn($q)=>$r->user()->isLineManager()?$q:$q->where('owner_id',$r->user()->id))->orderByDesc('week_start')->get()->unique(fn($p)=>\App\Services\ClientRelationsCentre::key($p->client_name.'|'.$p->project_name))->map(fn($p)=>['id'=>$p->id,'client'=>$p->client_name,'title'=>$p->project_name]):collect();
  $events=PerformanceEvent::with('actor')->where('entity_type','operations_handover')->whereIn('entity_id',$rows->pluck('id'))->orderBy('id')->get()->groupBy('entity_id');
  return response()->json(['items'=>$rows->map(function($h)use($flow,$r,$events){return ['id'=>$h->id,'revision'=>$h->revision,'project_id'=>$h->project_id,'client'=>$h->project->client_name,'project'=>$h->project->project_name,'title'=>$h->title,'plan'=>$h->plan,'criteria'=>$h->acceptance_criteria,'plan_url'=>$h->plan_path?route('portal.operations.handovers.file',$h):$h->plan_url,'plan_download'=>(bool)$h->plan_path,'requester'=>['id'=>$h->requester_id,'name'=>$h->requester?->name],'lead'=>['id'=>$h->lead_id,'name'=>$h->lead?->name??'Awaiting Operations HOD assignment'],'stage'=>$h->stage,'event_at'=>$h->event_at?->toIso8601String(),'setup_due_at'=>$h->setup_due_at?->toIso8601String(),'location'=>$h->location,'priority'=>$h->priority,'received'=>$h->created_at?->toIso8601String(),'acknowledged'=>$h->acknowledged_at?->toIso8601String(),'meeting'=>['scheduled'=>$h->meeting_scheduled_at?->toIso8601String(),'held'=>$h->meeting_held_at?->toIso8601String(),'location'=>$h->meeting_location,'minutes'=>$h->meeting_minutes,'attendees'=>$h->attendees??[],'cr_signoff'=>$h->cr_signoff_at?->toIso8601String(),'ops_signoff'=>$h->ops_signoff_at?->toIso8601String()],'resources'=>$h->resources??[],'evidence'=>$h->submission_evidence,'submitted'=>$h->submitted_at?->toIso8601String(),'accepted'=>$h->accepted_at?->toIso8601String(),'verified'=>$h->verified_at?->toIso8601String(),'quality'=>$h->quality_score,'can_plan'=>Workflow::lead($r->user())||(Workflow::ops($r->user())&&(int)$h->lead_id===$r->user()->id),'actor'=>$r->user()->id,'actions'=>$flow->allowed($r->user(),$h),'history'=>($events[$h->id]??collect())->map(fn($e)=>['action'=>$e->action,'actor'=>$e->actor?->name??'System','at'=>$e->created_at,'reason'=>$e->reason])];}),'pagination'=>['page'=>$rows->currentPage(),'last'=>$rows->lastPage(),'total'=>$rows->total()],'projects'=>$projects->values(),'can_create'=>Pipeline::member($r->user()),'staff'=>User::internalStaff()->where('status','active')->whereIn('department',[...User::departmentAliases('client_relations'),...User::departmentAliases('operations_projects')])->get()->map(fn($u)=>['id'=>$u->id,'name'=>$u->name,'department'=>User::normalizeDepartmentKey($u->department)])])->header('Cache-Control','private, no-store');
 }
 public function store(Request $r,Workflow $flow){$this->access($r);abort_unless(Pipeline::member($r->user()),403);$v=$r->validate(['project_id'=>'required|integer|exists:crm_pipeline_projects,id','title'=>'required|string|min:5|max:255','plan'=>'required|string|min:20|max:12000','acceptance_criteria'=>'required|string|min:10|max:8000','plan_url'=>'nullable|url:https|max:2000','plan_file'=>'nullable|file|mimes:pdf,jpg,jpeg,png,webp,docx,pptx,xlsx|max:20480','event_at'=>'required|date|after:now','setup_due_at'=>'required|date|before_or_equal:event_at|after:now','location'=>'required|string|max:255','priority'=>'required|in:Low,Medium,High,Urgent']);
  $p=CrmPipelineProject::findOrFail($v['project_id']);abort_unless($p->source_period_confirmed,422,'Confirm the source reporting date before handing this project over.');abort_unless($r->user()->isLineManager()||(int)$p->owner_id===$r->user()->id,403);
  if(OperationsHandover::where('project_id',$p->id)->where('title',$v['title'])->whereNotIn('stage',['cancelled'])->exists())return response()->json(['message'=>'This project already has a handover with that title. Update the existing handover.'],409);
  $path=null;if($r->hasFile('plan_file')){$file=$r->file('plan_file');app(CreativeUploadScreening::class)->check($file);$path=$file->store('operations-handovers','local');$v['plan_path']=$path;$v['plan_name']=mb_substr(basename($file->getClientOriginalName()),0,240);}unset($v['plan_file']);
  try{$h=DB::transaction(function()use($v,$r,$flow){$h=OperationsHandover::create($v+['requester_id'=>$r->user()->id,'stage'=>'submitted','resources'=>[]]);PerformanceWorkflow::record('operations_handover',$h->id,$r->user()->id,'submitted',[],$h->getAttributes(),'Client Relations plan submitted to Operations.');$flow->notify($h,'New Plan for Operations Handover');return $h;});}catch(\Throwable $e){if($path)Storage::disk('local')->delete($path);throw $e;}
  return response()->json(['id'=>$h->id,'message'=>'Plan sent to Operations. Its HOD will assign the lead and arrange the handover.'],201);
 }
 public function action(Request $r,OperationsHandover $handover,Workflow $flow){$this->access($r);$v=$r->validate(['revision'=>'required|integer|min:1','action'=>'required|in:assign,acknowledge,meeting,signoff_cr,signoff_ops,resource,planning,sourcing,setup,submit,accept,return,verify,cancel,comment','reason'=>'required|string|min:5|max:4000','performance_weight'=>'nullable|integer|min:1|max:5','lead_id'=>'nullable|integer|exists:users,id','meeting_scheduled_at'=>'nullable|date','meeting_held_at'=>'nullable|date|before_or_equal:now','meeting_location'=>'nullable|string|max:255','meeting_minutes'=>'nullable|string|min:10|max:8000','attendees'=>'nullable|array|max:100','attendees.*'=>'integer|exists:users,id','evidence_url'=>'nullable|url:https|max:2000','quality_score'=>'nullable|numeric|min:0|max:100','resource'=>'nullable|array','resource.id'=>'nullable|uuid','resource.category'=>'nullable|in:asset,vendor,third_party,promoter,logistics,other','resource.name'=>'nullable|string|max:255','resource.reference'=>'nullable|string|max:255','resource.quantity'=>'nullable|numeric|min:0.01|max:1000000','resource.owner_id'=>'nullable|integer|exists:users,id','resource.due_on'=>'nullable|date','resource.status'=>'nullable|in:needed,sourcing,confirmed,ready,not_required','resource.note'=>'nullable|string|max:2000']);
  $h=$flow->transition($handover,$r->user(),$v);return response()->json(['message'=>'Handover updated. Both teams have been notified.','stage'=>$h->stage,'revision'=>$h->revision]);
 }
 public function file(Request $r,OperationsHandover $handover){$this->access($r);abort_unless($handover->plan_path&&Storage::disk('local')->exists($handover->plan_path),404);return Storage::disk('local')->download($handover->plan_path,$handover->plan_name,['Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}
}
